import{J as e,n as t,ot as n,q as r}from"./chunks/framework.B5GhSpE5.js";var i=JSON.parse(`{"title":"Entity and tick re-architecture: one entity model, one tick pipeline","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Entity and tick re-architecture: one entity model, one tick pipeline"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/plans/entity-simulation-rearchitecture"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/plans/entity-simulation-rearchitecture"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/plans/entity-simulation-rearchitecture.md"}},"headers":[],"relativePath":"plans/entity-simulation-rearchitecture.md","filePath":"plans/entity-simulation-rearchitecture.md","lastUpdated":1794485700000}`),a={name:`plans/entity-simulation-rearchitecture.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="entity-and-tick-re-architecture-one-entity-model-one-tick-pipeline" tabindex="-1">Entity and tick re-architecture: one entity model, one tick pipeline <a class="header-anchor" href="#entity-and-tick-re-architecture-one-entity-model-one-tick-pipeline" aria-label="Permalink to “Entity and tick re-architecture: one entity model, one tick pipeline”">​</a></h1><p>Status: in progress. The decisions were taken on 2026-11-10 and this plan was written the same day. Counts in this page are from that day. Slices 0 to 2 have landed on the program branch (<code>t3/subagent-architecture-review</code>, pull request #2948), and slices 3 to 5 were in progress when work moved to another machine on 2026-11-10. <a href="/pr-preview/pr-3030/plans/entity-simulation-rearchitecture.handoff.html">The handoff</a> says where each package stands and how to pick it up.</p><p>The server runs two simulations of the same world and reconciles them every tick. Every data-driven mob lives once in <code>EntityRuntime</code> and a second time as a legacy body in the world&#39;s entity map, and health crosses between the two by comparison. Two entity indexes answer the same question under opposite rules. A tick awaits at 233 points, so a packet handler can change a player in the middle of it. This plan replaces all of that with one entity store, one index, a synchronous tick, and replication that reads a change log.</p><p>The decisions are in ADRs 0006 to 0018. This page holds what does not fit an ADR: what the review changed, the order of the work, how each slice is judged, and what is still unknown.</p><h2 id="priorities" tabindex="-1">Priorities <a class="header-anchor" href="#priorities" aria-label="Permalink to “Priorities”">​</a></h2><ol><li>The server feels like Minecraft and mostly is Minecraft, and it keeps up with Mojang&#39;s releases. That is why behavior comes from data and not from reimplementation.</li><li>Performance, a close second.</li><li>The program finishes. No slice ends with mobs on one model and players on another, and the slices that create a temporary mix are planned as one commitment.</li></ol><h2 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to “Decisions”">​</a></h2><ul><li><a href="/pr-preview/pr-3030/adr/0006-replay-determinism-contract.html">ADR 0006</a>: a replay gives identical digests at any host speed.</li><li><a href="/pr-preview/pr-3030/adr/0007-one-entity-index-visible-on-write.html">ADR 0007</a>: one entity index, and a write is visible to the next query.</li><li><a href="/pr-preview/pr-3030/adr/0008-one-entity-model.html">ADR 0008</a>: one entity model, with players and items in the same store.</li><li><a href="/pr-preview/pr-3030/adr/0009-external-inputs-enter-once-per-tick.html">ADR 0009</a>: external inputs enter once per tick and are recorded, and a handler&#39;s lane decides whether its packet is an input.</li><li><a href="/pr-preview/pr-3030/adr/0010-no-barrel-files.html">ADR 0010</a>: no barrel files, and explicit package exports.</li><li><a href="/pr-preview/pr-3030/adr/0011-a-world-exchanges-only-plain-data.html">ADR 0011</a>: a world exchanges only plain data with the outside.</li><li><a href="/pr-preview/pr-3030/adr/0012-the-change-log-is-the-history.html">ADR 0012</a>: the change log is the history, complete and invertible.</li><li><a href="/pr-preview/pr-3030/adr/0013-vetoable-actions-are-staged.html">ADR 0013</a>: vetoable actions run as intent, guard, compute and commit.</li><li><a href="/pr-preview/pr-3030/adr/0014-handlers-share-a-shape-and-run-in-the-input-step.html">ADR 0014</a>: handlers share one shape, and input-lane handlers run in the input step.</li><li><a href="/pr-preview/pr-3030/adr/0015-a-tick-is-a-fixed-sequence-of-synchronous-phases.html">ADR 0015</a>: a tick is a fixed sequence of synchronous phases.</li><li><a href="/pr-preview/pr-3030/adr/0016-replication-reads-the-change-log.html">ADR 0016</a>: replication reads the change log after the tick and keeps a replica.</li><li><a href="/pr-preview/pr-3030/adr/0017-one-lifecycle-event-bus.html">ADR 0017</a>: one lifecycle event bus.</li><li><a href="/pr-preview/pr-3030/adr/0018-a-save-is-a-snapshot-of-one-tick-boundary.html">ADR 0018</a>, proposed: a save is a snapshot of one tick boundary.</li></ul><h2 id="what-the-review-changed" tabindex="-1">What the review changed <a class="header-anchor" href="#what-the-review-changed" aria-label="Permalink to “What the review changed”">​</a></h2><p>The first version of this plan left ten gaps. Each one is closed below, with the evidence that closed it. Seven of them changed an ADR.</p><h3 id="replication-needs-more-than-the-current-tick-s-log" tabindex="-1">Replication needs more than the current tick&#39;s log <a class="header-anchor" href="#replication-needs-more-than-the-current-tick-s-log" aria-label="Permalink to “Replication needs more than the current tick&#39;s log”">​</a></h3><p>A player who walks into range of an entity that has not changed needs its full state, and the current tick&#39;s log has no entry for it. Today <code>spawnTo</code> reads position, rotation, metadata, attributes, equipment and effects from the live entity object and encodes a spawn packet for each viewer. Nothing caches replicated state.</p><p>Replication now keeps a replica, built only from the log. A membership entry carries an entity&#39;s full replicated state, and later entries update it. A first sight is answered from the replica and encoded once for each codec group. Replication still reads nothing from the simulation except the log, which keeps it movable to a worker. The cost is a second copy of the client-visible fields of each loaded entity, counted as replica entries and bytes. ADR 0016 records this.</p><h3 id="invertibility-needed-a-scope-and-a-use" tabindex="-1">Invertibility needed a scope and a use <a class="header-anchor" href="#invertibility-needed-a-scope-and-a-use" aria-label="Permalink to “Invertibility needed a scope and a use”">​</a></h3><p>ADR 0012 priced the before-values at three numbers for a moving entity, and authoritative state also includes blocks, inventories and block entities. Nothing in the program read a before-value.</p><p>Three things close this. First, the log has three entry kinds with stated inverses, and a chunk that enters the world is named in the log and not carried by it, because it arrived as an input. Second, a unit of work that throws is undone by inverting its span, which gives invertibility a use and a test inside the program and also closes the failure gap below. Third, this program keeps a tick&#39;s log only until replication and the save cut have read it. The before-values then cost memory for one tick and nothing on disk. Slice 2 reports deltas and bytes per tick on the replay scenarios as a non-gating count, so the retention work that comes later starts from real figures.</p><h3 id="the-tick-was-audited-for-awaits" tabindex="-1">The tick was audited for awaits <a class="header-anchor" href="#the-tick-was-audited-for-awaits" aria-label="Permalink to “The tick was audited for awaits”">​</a></h3><p>The handlers had been audited and the simulation had not. An audit of everything reachable from <code>World.update</code> found 233 awaits and about 20 promises the tick starts without awaiting.</p><table tabindex="0"><thead><tr><th>Class</th><th>Awaits</th><th>What removes them</th><th>Slice</th></tr></thead><tbody><tr><td>Packet sends</td><td>77</td><td>Sends become entries in the change log</td><td>7</td></tr><tr><td>Functions that are async only to pass a wait on</td><td>120</td><td>They become synchronous once the waits below them are gone</td><td>3 to 9</td></tr><tr><td>Chunk or block reads that may load a chunk</td><td>21</td><td>Loaded-chunk accessors, chunk tickets and waiting states</td><td>3, 5, 9</td></tr><tr><td>Disk reads and writes</td><td>4</td><td>Chunk loads as inputs, saves under ADR 0018</td><td>8, 9</td></tr><tr><td>Awaited events</td><td>3</td><td>Guards under ADR 0013</td><td>4, 9</td></tr><tr><td>Other waits</td><td>8</td><td>Worlds built outside ticks, completion results as inputs</td><td>9</td></tr></tbody></table><p>Most of the 233 are mechanical. The simulation never reads the result of a send, and <code>WorldSystems.tick</code>, <code>RaidManager.tick</code>, cooking stations, spawners, <code>EntityRuntime.tick</code> and the block-behaviors, engine-systems, lighting, spawning, entities, entity-goals and entity-brains packages contain no asynchronous code today.</p><p>Three sites are hard, and each needs a mechanism this plan now names.</p><ul><li>Portal transfer runs inside an entity&#39;s update (<code>Entity.ts:526</code>). It can build a dimension, generate chunks, raise a cancellable event and save player data. It becomes the message of ADR 0011: the source world commits the departure in its tick, and the destination admits the arrival as an input once its chunks are ready.</li><li>Respawn search runs inside <code>onDeath</code>, which runs inside <code>damage</code> (<code>Player.ts:988</code>). It is why every caller of <code>damage</code> is asynchronous, and the runtime starts <code>damage</code> without awaiting it. Death commits in the tick. The respawn point becomes a request to a world service, and its answer returns as an input.</li><li>The dragon fight loads its arena, gateway and pillar chunks inline (<code>DragonFight.ts:390</code>, <code>:512</code>, <code>:565</code>). It takes chunk tickets and gets explicit waiting states.</li></ul><p>Unloaded chunks are already handled the right way by most of the simulation. Block updates skip them, fluids and scheduled ticks read air and have their writes refused, and explosions and data-driven mobs read only loaded chunks. The code that loads a chunk from inside a tick is the legacy item entity, the player breath check, the dragon fight, portal travel and <code>World.setBlockRuntimeId</code>.</p><p>Each slice removes the awaits in the code it rewrites, and the count is reported from slice 1 on. The test that a tick completes without yielding can only pass at slice 9.</p><h3 id="the-temporary-mix-was-too-long" tabindex="-1">The temporary mix was too long <a class="header-anchor" href="#the-temporary-mix-was-too-long" aria-label="Permalink to “The temporary mix was too long”">​</a></h3><p>The first version kept a transitional adapter over legacy entities from slice 2 to slice 8 and deleted the legacy classes at the end. The legacy classes now go in slice 5, when players move, so the adapter lives for slices 2 to 5. Those four slices are one commitment. Slice 2 does not start until the work through slice 5 is planned.</p><p>Slice 5 is where the program is most likely to stall, because <code>Player</code> carries the entity, the connection, the saved record and server-wide chat and permissions. A spike before slice 2 puts one player-shaped entity into a prototype store, with an inventory, a network session that the entity references and a save and load round trip. The spike is thrown away. If it shows that a player cannot be expressed in the shape of ADR 0008, that ADR is reopened before any store code lands.</p><h3 id="one-input-step-would-have-throttled-chunk-streaming" tabindex="-1">One input step would have throttled chunk streaming <a class="header-anchor" href="#one-input-step-would-have-throttled-chunk-streaming" aria-label="Permalink to “One input step would have throttled chunk streaming”">​</a></h3><p>Of the 72 handler classes, 19 write authoritative state, 15 read it without writing, and 38 touch only their own connection. A sub-chunk request is answered in handler context today. Under one input step for every packet it would wait for the next tick and slow down with the tick rate.</p><p>ADR 0009 now defines three lanes. The connection lane and the read lane run when the packet arrives, and only input-lane packets are inputs. Four of the 15 readers relay something other players see (<code>ActorEvent</code>, <code>Animate</code>, <code>Emote</code>, <code>LevelSoundEvent</code>), so they belong in the input lane, where the relay becomes a log entry. The read lane is for handlers that reply only to the sender. <code>LevelChunk</code> delivery already runs from its own scheduler outside the tick and stays there.</p><p>The read lane narrows the outbound digest in ADR 0006. The digest covers what replication produces from the log, counted toward the tick that produced it. Read-lane replies and chunk streaming are outside it, because no tick decides when they leave. Today&#39;s recorder stamps a packet with the tick in which the transport framed it, which slice 7 changes.</p><h3 id="guards-have-to-replace-parameters" tabindex="-1">Guards have to replace parameters <a class="header-anchor" href="#guards-have-to-replace-parameters" aria-label="Permalink to “Guards have to replace parameters”">​</a></h3><p>The first version of ADR 0013 said a scripting before-hook could only pass or veto. In <code>@minecraft/server</code> 2.11.0, ten of the seventeen stable before-events let a script rewrite a parameter, such as the damage of <code>EntityHurtBeforeEvent</code> or the block list of <code>ExplosionBeforeEvent</code>. Bedrock add-ons are the primary way to extend the server, so a pass-or-veto rule would have ruled out a faithful host.</p><p>A guard now returns pass, veto or replacement values for the parameters its pipeline declares replaceable, and still writes no state. That matches the documented restricted execution of before-event callbacks. ADR 0017 changed for the same reason. Bedrock runs a <code>system.run</code> callback at the end of the same tick, so the ADR no longer places it in the next input step and leaves the point to the Script API host design.</p><h3 id="saves-had-no-rule" tabindex="-1">Saves had no rule <a class="header-anchor" href="#saves-had-no-rule" aria-label="Permalink to “Saves had no rule”">​</a></h3><p>A save pass mixes ticks today. Autosave starts in the middle of a tick, captures every player at that instant and then serializes chunks eight at a time across later ticks. A crash can leave an item in a saved inventory and also in a chest saved later. An entity that changes chunk during the pass can be written twice or not at all.</p><p>ADR 0018 proposes that a pass writes the state of one tick boundary and commits it as one atomic write. It is proposed and not accepted, because the commit is a synchronous LevelDB append on the server thread and its size is unknown. Slice 8 measures the bytes in a pass before the ADR is accepted.</p><h3 id="a-failed-update-left-partial-writes" tabindex="-1">A failed update left partial writes <a class="header-anchor" href="#a-failed-update-left-partial-writes" aria-label="Permalink to “A failed update left partial writes”">​</a></h3><p>ADR 0015 skipped an entity that throws and assumed the store stays consistent. An update that throws halfway has already written. The store now undoes the span of the unit that threw before it skips the entity, as described under invertibility above.</p><h3 id="slice-1-promised-too-much-and-proxies-had-no-slice" tabindex="-1">Slice 1 promised too much, and proxies had no slice <a class="header-anchor" href="#slice-1-promised-too-much-and-proxies-had-no-slice" aria-label="Permalink to “Slice 1 promised too much, and proxies had no slice”">​</a></h3><p>Slice 1 was named &quot;trustworthy replay&quot;, and replay is not fully trustworthy until the tick is synchronous. The slice list below says what replay guarantees after each step, and the target table names the slice at which each proxy starts to gate.</p><h2 id="slice-order" tabindex="-1">Slice order <a class="header-anchor" href="#slice-order" aria-label="Permalink to “Slice order”">​</a></h2><p>Every slice lands on <code>master</code>, and a slice deletes what it replaces. The one exception is the adapter over legacy entities, which slice 2 adds and slice 5 removes.</p><ol start="0"><li><strong>Barrel ban.</strong> Biome&#39;s <code>noBarrelFile</code> and <code>noReExportAll</code> with a baseline that only shrinks. No code changes. This slice is independent of the others and can land at any time.</li><li><strong>Tick boundaries.</strong> Every handler declares a lane. The dispatcher holds input-lane packets, and the ticker applies them at the start of the next tick in arrival order, which is what the replay harness already does when it injects. Capture stamps a packet with the tick that applied it. Chunk completions are recorded as inputs. Counts replace the 20 ms and 25 ms budgets. Worlds tick one after another in a fixed order, and a failing world does not skip the next. Handlers are still asynchronous here, so a tick can still yield, but no handler runs in the middle of one. After this slice, live play and its replay apply the same inputs at the same ticks.</li><li><strong>The entity store.</strong> The store, setters that append entries with before-values, spans and their inverses, the one index, and the adapter over legacy entities. The player spike comes first.</li><li><strong>Items and the eye of ender</strong> move into the store with built-in definitions. The item ground probe stops loading chunks.</li><li><strong>Staged damage and death.</strong> The store owns damage and death under ADR 0013, with replaceable parameters. The mirror and the health comparison are deleted. <code>damage</code> becomes synchronous, which removes the promises the runtime starts without awaiting. Respawn search becomes a world service request.</li><li><strong>Players</strong> move into the store, split into components, a network session and services for chat, permissions and persistence. <code>Entity</code>, <code>GenericEntity</code>, <code>Human</code>, the <code>Player</code> class and the adapter are deleted. No legacy entity remains after this slice.</li><li><strong>Handlers.</strong> The shared shape, a narrow context and synchronous input-lane handlers. The client package adopts the shape.</li><li><strong>Replication reads the log.</strong> Block and block entity writes go through logged setters, so the log is complete. Replication builds its replica, computes each audience once and encodes once for each codec group. Sends leave the simulation, which removes the largest class of awaits. Outbound packets count toward the tick that produced them.</li><li><strong>Saves at a tick boundary</strong>, if ADR 0018 is accepted after its measurement.</li><li><strong>The synchronous tick.</strong> Dimension travel as messages, chunk tickets and waiting states for the dragon fight, worlds built outside ticks, and tick functions admitted as inputs. After this slice a tick completes without yielding, and ADR 0006 holds in full.</li><li><strong>One lifecycle event bus.</strong></li><li><strong>Explicit exports.</strong> Prismarine&#39;s barrels and its <code>&quot;./*&quot;</code> export are replaced.</li></ol><p>Players come before replication so the log is complete when replication reads it. Handlers come before replication so they have somewhere to put their output. The cost of that order is that the encode-once change lands at slice 7.</p><h2 id="progress" tabindex="-1">Progress <a class="header-anchor" href="#progress" aria-label="Permalink to “Progress”">​</a></h2><p>As of 2026-11-10, at program head <code>646dd8a4f3</code>, rebased on <code>master</code> <code>9a2c1d5af5</code>. Every CI check passed on <code>46a1d6977a</code>, Client E2E included.</p><table tabindex="0"><thead><tr><th>Package</th><th>State</th></tr></thead><tbody><tr><td>A1 barrel ban, A2 count budgets and world order, A3 handler lanes, A4 change log module, A5 player spike</td><td>Landed</td></tr><tr><td>B1 input admission, with its two follow-up fixes (a held input blocked its connection; a stale move undid a teleport)</td><td>Landed</td></tr><tr><td>B2 chunk completions as recorded inputs, with the follow-up fix for the tick that stalled after the dragon died</td><td>Landed</td></tr><tr><td>B3a one live player per account (#2951) and the persistence service</td><td>Landed</td></tr><tr><td>B3b chat fan-out and respawn search as services</td><td>Done on <code>refactor/chat-fanout-respawn-service-v2</code>, not yet integrated</td></tr><tr><td>B4 save pass measurement, B5 re-keyed maps</td><td>Landed</td></tr><tr><td>C1a component state on the instance, C1b one entity index, C1c the entity store with logged setters, spans and undo</td><td>Landed</td></tr><tr><td>Replay determinism fixes (settle gaps, wall-clock chunk budget in the harness)</td><td>Landed</td></tr><tr><td>C2 items and the eye of ender in the store</td><td>Work in progress, not landed</td></tr><tr><td>C3 staged damage and death, the mirror deleted</td><td>Work in progress, not landed</td></tr><tr><td>C4 and everything in phases D to F</td><td>Not started</td></tr></tbody></table><h2 id="phases-and-work-packages" tabindex="-1">Phases and work packages <a class="header-anchor" href="#phases-and-work-packages" aria-label="Permalink to “Phases and work packages”">​</a></h2><p>A slice is too large to hand to one person or agent, and several slices have parts that do not depend on each other. The phases below cut the slices into work packages. Packages in one phase run side by side, each in its own worktree, and a phase starts when the packages it depends on have landed. Each package commits in small steps and passes the gate below before it is rebased onto the program branch.</p><h3 id="phase-a-foundations" tabindex="-1">Phase A: foundations <a class="header-anchor" href="#phase-a-foundations" aria-label="Permalink to “Phase A: foundations”">​</a></h3><p>Nothing here depends on another package, and no two packages edit the same files.</p><table tabindex="0"><thead><tr><th>Package</th><th>Slice</th><th>Work</th><th>Main files</th></tr></thead><tbody><tr><td>A1</td><td>0</td><td>Ban barrels with a baseline that only shrinks</td><td><code>biome.json</code>, <code>scripts/</code></td></tr><tr><td>A2</td><td>1</td><td>Counts replace the 20 ms and 25 ms budgets. Worlds tick one after another in a fixed order, and a failing world does not skip the next</td><td><code>World.ts</code>, <code>WorldSystems.ts</code>, <code>modules/ticker.ts</code></td></tr><tr><td>A3</td><td>1</td><td>Every handler declares a lane, and a test checks the registry. No handler changes when it runs yet</td><td><code>network/handler/</code>, <code>PacketHandlerRegistry.ts</code></td></tr><tr><td>A4</td><td>2</td><td>The change log as a module of its own: the three entry kinds, spans, inverses and the one-tick lifetime, with nothing wired to it</td><td>new module beside <code>world/</code></td></tr><tr><td>A5</td><td>2</td><td>The player spike. It is thrown away, and its findings are kept as a research note</td><td><code>docs/research/</code></td></tr></tbody></table><h3 id="phase-b-admission-and-preparation" tabindex="-1">Phase B: admission and preparation <a class="header-anchor" href="#phase-b-admission-and-preparation" aria-label="Permalink to “Phase B: admission and preparation”">​</a></h3><table tabindex="0"><thead><tr><th>Package</th><th>Slice</th><th>Depends on</th><th>Work</th></tr></thead><tbody><tr><td>B1</td><td>1</td><td>A2, A3</td><td>The dispatcher holds input-lane packets and the ticker applies them at tick start. Capture stamps the applying tick. The replay test compares two runs tick by tick</td></tr><tr><td>B2</td><td>1</td><td>A2</td><td>Chunk completions are recorded as inputs</td></tr><tr><td>B3</td><td>5</td><td>none</td><td>Player persistence, chat fan-out and respawn search move out of <code>Player</code> into services keyed by player identity, while <code>Player</code> is still a legacy entity</td></tr><tr><td>B4</td><td>8</td><td>none</td><td>Measure the bytes in a save pass and confirm what a saved player record copies, so ADR 0018 can be accepted or changed</td></tr><tr><td>B5</td><td>5</td><td>none</td><td>Re-key the seven maps keyed by the <code>Player</code> object by player identity or entity id</td></tr></tbody></table><p>B1 and B2 both edit the ticker, so B2 follows B1. B3, B4 and B5 run beside them.</p><p>The lane declarations of A3 put 35 handlers in the connection lane, 9 in the read lane and 28 in the input lane, and left B1 these rules.</p><ul><li>An input-lane packet is applied in the input step of the world its sender&#39;s entity is in. An effect on another world leaves as a message under ADR 0011 and is admitted at that world&#39;s next input step.</li><li>Server-wide state that is not a world&#39;s authoritative state, such as the operator list, the default game mode and chat fan-out, changes in memory when the handler runs and persists off the tick.</li><li>A player&#39;s removal is an input, whether a <code>Disconnect</code> packet or a closed transport caused it.</li><li><code>SubChunkRequest</code> can load a chunk the world evicted. The handler may wait for it, and the loaded chunk is admitted through the completion queue like any other.</li><li><code>Login</code> and <code>ClientToServerHandshake</code> stay in the connection lane although they read the default world&#39;s spawn and build the player. That work moves in front of the join in slice 6.</li></ul><p>Slice 6 inherits a list of what stops an input-lane handler from being synchronous. Eight handlers load chunks or search for a position, among them <code>PlayerAction</code>, <code>InventoryTransaction</code>, <code>ItemStackRequest</code>, <code>Respawn</code> and <code>RequestChunkRadius</code>. Six reach the disk through <code>savePlayerData</code>, the operator file or the config. <code>Text</code>, <code>CommandRequest</code> and <code>SettingsCommand</code> call into commands and chat, which can do anything. Six read-lane handlers are write requests the server drops today, and each moves to the input lane when its write is implemented.</p><p>B2 left three things for later slices to remove.</p><ul><li><code>world/TickContext.ts</code> uses <code>AsyncLocalStorage</code> to tell code inside a tick from code between ticks, because the tick still awaits. Slice 9 makes the tick synchronous, and a plain flag set by the ticker replaces it then.</li><li>Eight code paths still load a chunk from inside a tick. Each is admitted inline, recorded as <code>inline</code> and listed in <code>IN_TICK_CHUNK_LOADS</code>, and a test fails when one is removed without updating the list. Slices 3, 5, 6 and 9 remove them.</li><li><code>World.disable</code> waits for an unload parked on admission, so calling it from inside a tick would never finish. Nothing does today. Slice 9 has to keep it that way or drain admissions first.</li><li>A tick that awaits work started outside it, such as from an event or a command between ticks, cannot be told apart from one that waits for its own chunks, and a chunk that work loads waits for the next input step. The ticker therefore admits every held completion inline, recorded as <code>inline</code>, and logs a <code>TickStalledError</code> each <code>TICK_STALL_MS</code> a tick runs with completions held. Slice 9&#39;s synchronous tick removes the wait and the watch with it.</li></ul><p>C1a and C1b left these for later packages.</p><ul><li>C1a moved component state the entities package hid in <code>WeakMap</code>s onto <code>EntityInstance.componentState</code>, with one write path that reports each write&#39;s before and after values to <code>EntityEnvironment.componentStateWritten</code>. <code>target_nearby_sensor</code> keeps a runtime id there, and runtime ids are drawn again each session, so C1c marks that field as not saved until the store has ids that survive a reload.</li><li>C1b left one index per dimension (<code>EntityIndex</code>, <code>World.getEntityIndex()</code>), and chunk membership as a second structure written only by <code>World.entityRelocated</code>. Membership follows the client body and the index follows the runtime&#39;s position, so the two agree again once C3 deletes the mirror. Until then legacy explosions search four blocks beyond their reach.</li><li>Viewer tracking still passes every entity in the world to <code>EntityTracker.plan</code>. D4 replaces that with audiences computed from the index.</li><li>Inside the tick, <code>World.getEntities()</code> is still copied for spawner counts, the attribute flush and tracking, and <code>EntityRuntime.all()</code> is copied for the entity pass, the despawn cycle and the mirror&#39;s <code>sync</code>. Slice 5&#39;s target removes the copies.</li></ul><p>C1c left these for later packages.</p><ul><li>The store is <code>EntityRuntime.store</code>, which took over the runtime&#39;s entity map, and it holds the world&#39;s change log until block writes join it in D3. A log tick is numbered by the store, not by the level clock, which <code>/time set</code> moves backwards.</li><li>A player&#39;s inventory is not logged. A slot changes by mutating the <code>Item</code> in place and <code>Inventory</code> does not know its owner, so from slice 2 to slice 5 the replay digest covers player inventories only through its snapshot. C4c&#39;s inventory with one entry per slot closes this. Legacy position, health and game mode are logged through <code>entity/legacyAdapter.ts</code>.</li><li>A merchant&#39;s offers are saved and hashed but not logged, because a trade changes the <code>Merchant</code> in place.</li><li>An undo restores only what a save or the digest reads. Goal progress, pending deaths and other runtime bookkeeping stay as the throw left them.</li><li>A chunk admitted inline inside a unit pins the unit, which then keeps its writes if it throws, until slices 3 to 9 remove the inline loads.</li><li>Writes between ticks, such as tick functions, which run after the worlds seal, and connection-lane handlers, are counted as unlogged and not logged.</li><li>A player whose update throws is not contained yet: legacy updates do not run as units. When players move into the store, the store&#39;s failure count disconnects the session instead of removing the entity.</li></ul><p>B3b left these for C3 and C4.</p><ul><li>Chat fan-out is <code>ChatManager</code>. A player joins it as a <code>ChatRecipient</code>, keyed by <code>keyOfPlayer</code>, with a <code>receive</code> callback, and the manager decides the audience and builds the line. Each recipient is still its own <code>chat</code> listener, because a listener that cancels the event stops only the players who joined after it. One listener with one audience pass is the shape D4 wants, and it changes which players such a listener stops, so it belongs with the guards of ADR 0013 or the event bus of slice 10.</li><li>Respawn search is <code>RespawnSearch</code> in <code>world/RespawnSearch.ts</code>, one for each level (<code>Level.getRespawnSearch</code>). <code>find(request)</code> takes the player&#39;s key, saved spawn point and body as plain data. It answers with <code>spawn</code> (<code>own</code> or <code>world</code>), the dimension, the three exchange positions and <code>spawnPointLost</code>, and writes nothing. Every world read is behind its <code>RespawnWorlds</code> port: building the bed&#39;s dimension, the bed and feet checks, and the world spawn, which can still run the search for dry land.</li><li><code>Player.getRespawnPoint</code> is the adapter. It builds the request, applies <code>spawnPointLost</code> by clearing the point and sending <code>tile.bed.notValid</code>, and resolves the answer&#39;s world. <code>onDeath</code>, <code>respawn</code>, <code>RespawnHandler</code> and <code>DimensionTravel.leaveEnd</code> call it. For C3, <code>onDeath</code> sends the request instead of awaiting the adapter, and the input that admits the answer applies <code>spawnPointLost</code> and sends the <code>SearchingForSpawn</code>. The in-tick chunk load entry for the search names <code>RespawnSearch.ts</code> and slice 4.</li><li>The request does not carry the world spawn. Reading it before the search would run the search for dry land even when the player&#39;s own point holds, so the service reads it only when it falls back to it.</li><li>For C4, the request&#39;s spawn point comes from the store entity&#39;s component, and the chat recipient&#39;s <code>receive</code> finds the session through the session registry by identity.</li></ul><h3 id="phase-c-the-store" tabindex="-1">Phase C: the store <a class="header-anchor" href="#phase-c-the-store" aria-label="Permalink to “Phase C: the store”">​</a></h3><table tabindex="0"><thead><tr><th>Package</th><th>Slice</th><th>Depends on</th><th>Work</th></tr></thead><tbody><tr><td>C1</td><td>2</td><td>A4, A5, B1</td><td>The entity store, logged setters, the one index and the adapter over legacy entities. Component state the entities package keeps in <code>WeakMap</code>s moves onto the instance, where the store can log and save it</td></tr><tr><td>C2</td><td>3</td><td>C1</td><td>Items and the eye of ender move into the store</td></tr><tr><td>C3</td><td>4</td><td>C1</td><td>Staged damage and death, the mirror deleted, <code>damage</code> synchronous</td></tr><tr><td>C4</td><td>5</td><td>C2, C3, B3, B5</td><td>Players move into the store. The legacy entity classes and the adapter are deleted. Split into the packages below</td></tr></tbody></table><p>C2 and C3 run side by side if C1 leaves item code and damage code in separate files. Otherwise C3 follows C2.</p><p><a href="/pr-preview/pr-3030/research/player-entity-spike.html">The player spike</a> found that a player fits the store with three host rules, which ADR 0008 now records, and that C4 is too large for one package. 79 source files and 117 test files name <code>Player</code>. C4 splits as follows.</p><table tabindex="0"><thead><tr><th>Package</th><th>Depends on</th><th>Work</th></tr></thead><tbody><tr><td>C4b</td><td>C1, C3</td><td>The player overlay, the rule that the client owns a player&#39;s movement, and a death that keeps the entity</td></tr><tr><td>C4c</td><td>C1</td><td>Player components with logged setters, and an inventory that logs one entry for each slot</td></tr><tr><td>C4d</td><td>C4b, C4c</td><td>Player systems: hunger, breath, fall damage, consumption and mining, reading loaded chunks only</td></tr><tr><td>C4e</td><td>C4c, B3</td><td>Persistence from the store entity, with the saved record unchanged</td></tr><tr><td>C4f</td><td>C4c</td><td>The session holds the entity id. Convert the files that name <code>Player</code>, split by directory</td></tr><tr><td>C4g</td><td>C4b, C4c</td><td>Show store players to clients through the current replicator until slice 7</td></tr><tr><td>C4h</td><td>C4b to C4g</td><td>Convert the tests, then delete the legacy entity classes and the adapter</td></tr></tbody></table><p>C4b and C4c run side by side. C4d, C4e, C4f and C4g run side by side after C4c. The spike&#39;s note lists what the adapter of C1 must provide while players are still legacy, and that list is part of C1&#39;s brief. One item needs an answer when C3 lands: the mirror is what shows store mobs to legacy sessions today, so from the slice that deletes it until slice 5 something else has to encode them.</p><p>The change log module of A4 left questions for C1, answered here.</p><ul><li>A chunk entering the world is a unit of its own. The input step admits a chunk as one input, and no other write shares its span, so a span that would have to be undone never holds a chunk entry.</li><li>A membership entry carries one record, the entity&#39;s saved form, and that form has to contain everything replication sends on first sight. ADR 0012 and ADR 0016 describe the same record.</li><li>Inverses are written through setters that do not log. If writing an inverse throws, the store can no longer be trusted, so the world stops ticking and reports the failure. It does not go on with a half-undone unit.</li><li>A chest&#39;s slots are fields of its block entity, addressed by block position. An entity&#39;s inventory slots are addressed by entity id.</li></ul><h3 id="phase-d-handlers-and-replication" tabindex="-1">Phase D: handlers and replication <a class="header-anchor" href="#phase-d-handlers-and-replication" aria-label="Permalink to “Phase D: handlers and replication”">​</a></h3><table tabindex="0"><thead><tr><th>Package</th><th>Slice</th><th>Depends on</th><th>Work</th></tr></thead><tbody><tr><td>D1</td><td>6</td><td>C4</td><td>The shared handler shape in <code>@jsprismarine/protocol</code> and the narrow server context</td></tr><tr><td>D2</td><td>6</td><td>D1</td><td>Convert the input-lane handlers to the shape, split into groups that run side by side. The client adopts the shape</td></tr><tr><td>D3</td><td>7</td><td>C4</td><td>Block and block entity writes go through logged setters</td></tr><tr><td>D4</td><td>7</td><td>D2, D3</td><td>The replica, one audience per change, one encode per codec group, and sends out of the simulation</td></tr></tbody></table><p>D3 runs beside D1 and D2.</p><h3 id="phase-e-the-synchronous-tick" tabindex="-1">Phase E: the synchronous tick <a class="header-anchor" href="#phase-e-the-synchronous-tick" aria-label="Permalink to “Phase E: the synchronous tick”">​</a></h3><table tabindex="0"><thead><tr><th>Package</th><th>Slice</th><th>Depends on</th><th>Work</th></tr></thead><tbody><tr><td>E1</td><td>8</td><td>D3, B4</td><td>Saves at a tick boundary, if ADR 0018 is accepted</td></tr><tr><td>E2</td><td>9</td><td>D4</td><td>Dimension travel as messages, and worlds built outside ticks</td></tr><tr><td>E3</td><td>9</td><td>D4</td><td>Chunk tickets and waiting states for the dragon fight</td></tr><tr><td>E4</td><td>9</td><td>E2, E3</td><td>Tick functions as inputs, and the test that a tick completes without yielding</td></tr></tbody></table><p>E1, E2 and E3 run side by side.</p><h3 id="phase-f-cleanup" tabindex="-1">Phase F: cleanup <a class="header-anchor" href="#phase-f-cleanup" aria-label="Permalink to “Phase F: cleanup”">​</a></h3><table tabindex="0"><thead><tr><th>Package</th><th>Slice</th><th>Depends on</th><th>Work</th></tr></thead><tbody><tr><td>F1</td><td>10</td><td>E4</td><td>One lifecycle event bus</td></tr><tr><td>F2</td><td>11</td><td>F1</td><td>Explicit exports for Prismarine, split by directory</td></tr></tbody></table><h2 id="the-gate-for-each-slice" tabindex="-1">The gate for each slice <a class="header-anchor" href="#the-gate-for-each-slice" aria-label="Permalink to “The gate for each slice”">​</a></h2><ul><li>Typecheck, lint and tests pass.</li><li>The parity families the slice touches pass.</li><li>Replay digests are unchanged, or are re-baselined in a separate commit that states the intended change. Until slice 9 this compares one replay with another under the guarantees listed for the slices already landed.</li><li>A client e2e scenario covers any client-visible change.</li><li>The proxy tests that gate at this slice pass.</li><li>A Changeset for each affected package follows <a href="/pr-preview/pr-3030/guide/versioning.html">the versioning policy</a>.</li><li>The docs the slice invalidates are updated, such as <a href="/pr-preview/pr-3030/data-driven/entities.html">entities</a>, <a href="/pr-preview/pr-3030/data-driven/engine-systems.html">engine systems</a> and the status in <a href="/pr-preview/pr-3030/plans/server-rearchitecture.html">the server re-architecture plan</a>.</li></ul><h2 id="performance-targets" tabindex="-1">Performance targets <a class="header-anchor" href="#performance-targets" aria-label="Permalink to “Performance targets”">​</a></h2><p>Each target is a count or a structure asserted in a test. None is a duration.</p><table tabindex="0"><thead><tr><th>Target</th><th>Gates from slice</th></tr></thead><tbody><tr><td>Every handler declares a lane, checked against the handler registry</td><td>1</td></tr><tr><td>No wall-clock read inside the world systems phase, with <code>performance.now</code> stubbed to throw</td><td>1</td></tr><tr><td>A replay applies each recorded input at the tick the capture stamped</td><td>1</td></tr><tr><td>An index query examines at most the candidates in the cells it touches, on a fixed scenario</td><td>2</td></tr><tr><td>Applying a span and then its inverse leaves the replay digest unchanged, for every entry kind</td><td>2</td></tr><tr><td>An idle world appends no entries, and N walking mobs append at most N position entries in a tick</td><td>2</td></tr><tr><td>No mirror class and no health comparison</td><td>4</td></tr><tr><td>No <code>Entity</code>, <code>GenericEntity</code> or <code>Human</code> class, and no array copy through <code>all()</code> or <code>getEntities()</code></td><td>5</td></tr><tr><td>No <code>Server</code> import in a handler</td><td>6</td></tr><tr><td>Encode calls for one broadcast occurrence equal the number of codec and compression groups</td><td>7</td></tr><tr><td>Replication visits entities in proportion to log entries, not to the number of entities</td><td>7</td></tr><tr><td>A snapshot plus the log reproduces the replay digest</td><td>7</td></tr><tr><td>A tick makes no wall-clock read and completes without yielding</td><td>9</td></tr><tr><td>No barrel in Prismarine</td><td>11</td></tr></tbody></table><p>Three counts are reported and do not gate: awaits reachable from <code>World.update</code>, change log entries and bytes per tick, and replica entries and bytes. They go through <code>reportProgress</code>.</p><h2 id="scope-notes" tabindex="-1">Scope notes <a class="header-anchor" href="#scope-notes" aria-label="Permalink to “Scope notes”">​</a></h2><p>Handlers take a narrow context and not <code>Server</code>. Other files that take <code>Server</code> stay out of the program, unless a codemod or delegated agents can convert them mechanically with no real risk. Then they go in.</p><h2 id="deferred" tabindex="-1">Deferred <a class="header-anchor" href="#deferred" aria-label="Permalink to “Deferred”">​</a></h2><ul><li>The Script API host. Its before-hooks are guards under ADR 0013. A wall-clock watchdog for long scripts would conflict with <a href="/pr-preview/pr-3030/adr/0009-external-inputs-enter-once-per-tick.html">ADR 0009</a>, and the host design has to answer that and pick the point in a tick where <code>system.run</code> callbacks run.</li><li>The low-level plugin form (&quot;mods&quot;). Keep the store&#39;s plain-data edge and the explicit exports in mind, and build nothing for it now.</li><li>Moving replication, a world or pathfinding to another thread. <a href="/pr-preview/pr-3030/adr/0011-a-world-exchanges-only-plain-data.html">ADR 0011</a> lists the candidates. A world on its own thread also moves the read lane onto the replica.</li><li>Retention of the change log, crash recovery from it, and rollback tooling.</li></ul><h2 id="checks-to-run-not-assumed" tabindex="-1">Checks to run, not assumed <a class="header-anchor" href="#checks-to-run-not-assumed" aria-label="Permalink to “Checks to run, not assumed”">​</a></h2><ul><li>Advancement triggers fire inline from the legacy damage and death methods. Reading them from the log changes when they fire, so slices 4 and 7 need a parity check on advancement timing.</li><li>Rejecting an interaction with an unloaded chunk should match Java. The parity suite has to confirm it in slice 6.</li><li>Counts in place of the 20 ms and 25 ms budgets mean an overloaded host ticks slower and never simulates differently. Slice 1 needs a scenario that shows the tick counter lagging with identical digests.</li><li><code>SubChunkRequest</code> can load an evicted chunk that was already announced (<code>PlayerSession.ts:578</code>). The read lane allows the wait, and slice 1 has to confirm the load reaches the world as an input.</li><li><code>World.replayStateDigest</code> calls <code>dataEntities().persist()</code> before it hashes, so taking a digest has a side effect. Slice 2 has to remove it or show it changes nothing.</li><li>The replay test asserts only that one tick has a digest. Slice 1 should make it compare two runs tick by tick before anything depends on it.</li><li>How the path finder treats a read from an unloaded chunk was not traced.</li><li>Whether a saved player&#39;s inventory record is a deep copy was not confirmed. Slice 8 depends on it.</li><li>Tick functions run from the ticker after the worlds, and a function can act in another dimension. Slice 9 treats a function as an input to the world it runs in and a cross-world command as a message. Confirm against Bedrock when a function runs relative to the tick.</li><li>The handler lanes were assigned from each handler&#39;s direct calls and not from a full trace. Slice 1 reviews the 15 readers and the <code>Disconnect</code> handler one by one.</li></ul></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};